You may not want to rely too much on `beforeunload` events though as it is unreliable on mobile, a good practice if you want to send analytics if to listen to the page visibility:<p><pre><code>  document.addEventListener(&#x27;visibilitychange&#x27;, () =&gt; {
    if (document.visibilityState === &#x27;hidden&#x27;) {
      navigator.sendBeacon(...);
    }
  });
</code></pre>
Of course it can&#x27;t strictly be considered a &quot;page leave&quot; but for mobile users it&#x27;s often your best bet: <a href="https:&#x2F;&#x2F;developer.chrome.com&#x2F;docs&#x2F;web-platform&#x2F;page-lifecycle-api#legacy-lifecycle-apis-to-avoid" rel="nofollow">https:&#x2F;&#x2F;developer.chrome.com&#x2F;docs&#x2F;web-platform&#x2F;page-lifecycl...</a>

You don&#x27;t have to. Passing cpu and memory works as well.<p><pre><code>    pc.ComputeContext{
        cpus=4, 
        memory=16
    }
</code></pre>
We are working on a minimal cluster and auto-scaling based on the query.

9 lines seem to be sufficient (assuming string keys and int values).<p><pre><code>    &#x2F;&#x2F; Hashtable definition
    #include &lt;string.h&gt;
    #define N 1024
    int* map_ptr(const char **keys, int *values, const char *key){
        size_t h = 0, c = 0, i;
        for (const char *c = key; *c; c++) h = h * 33 + *(unsigned char*)c;
        for (i = h % N; c &lt; N &amp;&amp; keys[i] &amp;&amp; 0 != strcmp(keys[i], key); i = (i + 1) % N, c++);
        if (!keys[i]) keys[i] = key;
        return 0 == strcmp(keys[i], key) ? &amp;values[i] : NULL;
    }

    &#x2F;&#x2F; Example usage
    const char *keys[N];
    int values[N];

    #include &lt;stdio.h&gt;

    int main(){
        &#x2F;&#x2F; Set some values
        *map_ptr(keys, values, &quot;one&quot;) = 1;
        *map_ptr(keys, values, &quot;two&quot;) = 2;
        *map_ptr(keys, values, &quot;three&quot;) = 3;

        &#x2F;&#x2F; Retrieve values
        printf(&quot;one: %i\n&quot;, *map_ptr(keys, values, &quot;one&quot;));
        printf(&quot;two: %i\n&quot;, *map_ptr(keys, values, &quot;two&quot;));
        printf(&quot;three: %i\n&quot;, *map_ptr(keys, values, &quot;three&quot;));

        return 0;
    }</code></pre>
